function fronts(rows, q, T) {
  const F = new Int32Array(T - q);
  for (let t = 0; t + q < T; t++) {
    const a = rows[t], c = rows[t + q];
    let x = -1;
    const n = Math.min(a.length, c.length);
    for (let i = 0; i < n; i++) {
